document.addEventListener('alpine:init', () => {
  Alpine.data('webAppPage', () => ({
    approved: false,
    scope: 'full',
    observer: null,
    motionQuery: null,
    desktopQuery: null,
    onMotionChange: null,
    onDesktopChange: null,
    init() {
      this.motionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
      this.desktopQuery = window.matchMedia('(min-width: 800px)');
      this.onMotionChange = (event) => { if (event.matches) this.showAll(); };
      this.onDesktopChange = (event) => { if (event.matches) this.closeMenu(false); };
      this.motionQuery.addEventListener('change', this.onMotionChange);
      this.desktopQuery.addEventListener('change', this.onDesktopChange);
      document.documentElement.classList.add('enhanced');
    },
    setupReveals() {
      if (this.motionQuery.matches || !('IntersectionObserver' in window)) {
        this.showAll();
        return;
      }
      this.observer = new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
          if (!entry.isIntersecting) return;
          entry.target.classList.add('is-visible');
          this.observer.unobserve(entry.target);
        });
      }, { threshold: 0.07 });
      this.$root.querySelectorAll('[data-reveal]').forEach((element) => {
        if (element.getBoundingClientRect().top < window.innerHeight) {
          element.classList.add('is-visible');
        } else {
          element.classList.add('reveal-armed');
          this.observer.observe(element);
        }
      });
    },
    showAll() {
      if (this.observer) this.observer.disconnect();
      this.$root.querySelectorAll('[data-reveal]').forEach((element) => {
        element.classList.remove('reveal-armed');
        element.classList.add('is-visible');
      });
    },
    closeMenu(restoreFocus = false) {
      this.$refs.menu.open = false;
      if (restoreFocus) this.$refs.menuToggle.focus();
    },
    navigate(event) {
      const target = document.querySelector(event.currentTarget.getAttribute('href'));
      this.closeMenu(false);
      if (!target) return;
      this.$nextTick(() => {
        target.setAttribute('tabindex', '-1');
        target.focus({ preventScroll: true });
        target.addEventListener('blur', () => target.removeAttribute('tabindex'), { once: true });
      });
    },
    destroy() {
      if (this.observer) this.observer.disconnect();
      this.motionQuery.removeEventListener('change', this.onMotionChange);
      this.desktopQuery.removeEventListener('change', this.onDesktopChange);
      document.documentElement.classList.remove('enhanced');
    }
  }));
});
